local GIRL_B64 = ""
local TG_B64 = ""

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function b64decode(data)
    local out = {}
    local buf, bits = 0, 0
    for i = 1, #data do
        local c = string.sub(data, i, i)
        if c == "=" then break end
        local v = string.find(B64, c, 1, true)
        if v then
            buf = (buf * 64 + (v - 1)) % 16777216
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                table.insert(out, string.char(math.floor(buf / 2 ^ bits) % 256))
            end
        end
    end
    return table.concat(out)
end

local function makeImage(w, h, b64)
    local ok, result = pcall(function()
        local raw = b64decode(b64)
        local image = game:GetService("AssetService"):CreateEditableImage({ Size = Vector2.new(w, h) })
        image:WritePixelsBuffer(Vector2.zero, Vector2.new(w, h), buffer.fromstring(raw))
        return Content.fromObject(image)
    end)
    if ok then return result end
    return nil
end

