    local host = hub and hub:FindFirstChild("Toasts")
    if not host then return end

    local list = host:FindFirstChildOfClass("UIListLayout")
    if list then list.Padding = UDim.new(0, 8) end

    local card = Instance.new("Frame")
    card.Name = "KomaruToast"
    card.Size = UDim2.new(1, 0, 0, 62)
    card.BackgroundColor3 = Color3.fromRGB(26, 28, 33)
    card.BorderSizePixel = 0
    card.ClipsDescendants = true
    card.Parent = host

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 10)
    corner.Parent = card

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(52, 55, 63)
    stroke.Thickness = 1
    stroke.Transparency = 0.15
    stroke.Parent = card

    local circle = Instance.new("Frame")
    circle.Name = "Circle"
    circle.Size = UDim2.fromOffset(34, 34)
    circle.Position = UDim2.new(0, 14, 0.5, -2)
    circle.AnchorPoint = Vector2.new(0, 0.5)
    circle.BackgroundColor3 = Color3.fromRGB(18, 45, 31)
    circle.BorderSizePixel = 0
    circle.ZIndex = 2
    circle.Parent = card
    local circleCorner = Instance.new("UICorner")
    circleCorner.CornerRadius = UDim.new(1, 0)
    circleCorner.Parent = circle
    local circleStroke = Instance.new("UIStroke")
    circleStroke.Color = GREEN
    circleStroke.Thickness = 1.5
    circleStroke.Transparency = 0.25
    circleStroke.Parent = circle

    local check = Instance.new("TextLabel")
    check.BackgroundTransparency = 1
    check.Size = UDim2.fromScale(1, 1)
    check.Text = "✓"
    check.TextColor3 = GREEN
    check.Font = Enum.Font.GothamBold
    check.TextSize = 17
    check.ZIndex = 3
    check.Parent = circle

    local titleLabel = Instance.new("TextLabel")
    titleLabel.BackgroundTransparency = 1
    titleLabel.Position = UDim2.new(0, 60, 0, 13)
    titleLabel.Size = UDim2.new(1, -72, 0, 18)
    titleLabel.Font = Enum.Font.GothamBold
    titleLabel.TextSize = 14
    titleLabel.TextColor3 = TEXT
    titleLabel.TextXAlignment = Enum.TextXAlignment.Left
    titleLabel.Text = title
    titleLabel.ZIndex = 2
    titleLabel.Parent = card

    local descLabel = Instance.new("TextLabel")
    descLabel.BackgroundTransparency = 1
    descLabel.Position = UDim2.new(0, 60, 0, 32)
    descLabel.Size = UDim2.new(1, -72, 0, 16)
    descLabel.Font = Enum.Font.Gotham
    descLabel.TextSize = 12
    descLabel.TextColor3 = MUTED
    descLabel.TextXAlignment = Enum.TextXAlignment.Left
    descLabel.TextTruncate = Enum.TextTruncate.AtEnd
    descLabel.Text = desc
    descLabel.ZIndex = 2
    descLabel.Parent = card

    local progress = Instance.new("Frame")
    progress.Name = "Progress"
    progress.Size = UDim2.new(1, 0, 0, 2)
    progress.Position = UDim2.new(0, 0, 1, -2)
    progress.BackgroundColor3 = GREEN
    progress.BorderSizePixel = 0
    progress.ZIndex = 3
    progress.Parent = card

    local tweenService = game:GetService("TweenService")
    tweenService:Create(progress, TweenInfo.new(3, Enum.EasingStyle.Linear), {
        Size = UDim2.new(0, 0, 0, 2),
    }):Play()

    card.BackgroundTransparency = 1
    stroke.Transparency = 1
    titleLabel.TextTransparency = 1
    descLabel.TextTransparency = 1
    check.TextTransparency = 1
    for _, child in ipairs(circle:GetChildren()) do
        if child:IsA("UIStroke") then child.Transparency = 1 end
    end
    tweenService:Create(card, TweenInfo.new(0.14), { BackgroundTransparency = 0 }):Play()
    tweenService:Create(stroke, TweenInfo.new(0.14), { Transparency = 0.15 }):Play()
    tweenService:Create(titleLabel, TweenInfo.new(0.14), { TextTransparency = 0 }):Play()
    tweenService:Create(descLabel, TweenInfo.new(0.14), { TextTransparency = 0 }):Play()
    tweenService:Create(check, TweenInfo.new(0.14), { TextTransparency = 0 }):Play()
    tweenService:Create(circleStroke, TweenInfo.new(0.14), { Transparency = 0.25 }):Play()

    task.delay(3, function()
        if not card.Parent then return end
        tweenService:Create(card, TweenInfo.new(0.22), { BackgroundTransparency = 1 }):Play()
        tweenService:Create(stroke, TweenInfo.new(0.22), { Transparency = 1 }):Play()
        tweenService:Create(titleLabel, TweenInfo.new(0.22), { TextTransparency = 1 }):Play()
        tweenService:Create(descLabel, TweenInfo.new(0.22), { TextTransparency = 1 }):Play()
        tweenService:Create(check, TweenInfo.new(0.22), { TextTransparency = 1 }):Play()
        tweenService:Create(circleStroke, TweenInfo.new(0.22), { Transparency = 1 }):Play()
        task.wait(0.25)
        card:Destroy()
    end)
end

local function copy(url, name)
    pcall(function() setclipboard(url) end)
    toast(name, "Link copied: " .. shortLink(url))
end

