    local button = Instance.new("TextButton")
    button.Name = name
    button.Size = UDim2.fromOffset(34, 34)
    button.Position = UDim2.new(1, x, 0, 31)
    button.AnchorPoint = Vector2.new(1, 0.5)
    button.ZIndex = 5
    button.BackgroundTransparency = 1
    button.Text = ""
    button.Parent = header

    local face = Instance.new("ImageLabel")
    face.Name = "Face"
    face.BackgroundTransparency = 1
    face.Size = UDim2.fromScale(1, 1)
    face.Image = TEX .. "tile9_r5_v7.png"
    face.ImageColor3 = Color3.fromRGB(24, 25, 30)
    face.ImageTransparency = 0
    face.ZIndex = 5
    face.Parent = button

    local faceGrad = Instance.new("UIGradient")
    faceGrad.Color = ColorSequence.new(Color3.fromRGB(37, 39, 46), Color3.fromRGB(17, 18, 22))
    faceGrad.Rotation = 90
    faceGrad.Parent = face

    local rim = Instance.new("ImageLabel")
    rim.Name = "Rim"
    rim.BackgroundTransparency = 1
    rim.Size = UDim2.fromScale(1, 1)
    rim.Image = TEX .. "rim9_r5_v7.png"
    rim.ImageColor3 = Color3.fromRGB(92, 95, 108)
    rim.ImageTransparency = 0.45
    rim.ZIndex = 7
    rim.Parent = button

    local icon = Instance.new("ImageLabel")
    icon.Name = "Icon"
    icon.BackgroundTransparency = 1
    icon.Size = UDim2.fromScale(0.62, 0.62)
    icon.Position = UDim2.fromScale(0.5, 0.5)
    icon.AnchorPoint = Vector2.new(0.5, 0.5)
    icon.ZIndex = 8
    if iconContent then
        icon.Size = UDim2.fromScale(0.72, 0.72)
        icon.Image = ""
        icon.ImageContent = iconContent
    else
        icon.Image = iconImage
    end
    icon.Parent = button

    button.MouseButton1Click:Connect(function()
        copy(url, name)
    end)
    return button
end

local function applyLogo(hub)
    if not GIRL then return end
    for _, target in ipairs({ hub.Root.Window.Sidebar.Brand, hub.Launcher.Card.Row }) do
        for _, child in ipairs(target:GetDescendants()) do
            if child:IsA("ImageLabel") and child.Name == "Mark" then
                if child.ImageContent ~= GIRL then
                    child.Image = ""
                    child.ImageColor3 = Color3.new(1, 1, 1)
                    pcall(function() child.ImageContent = GIRL end)
                end
            end
        end
    end
end

local function patchJoinDiscord(core)
    local parked = core:FindFirstChild("PulseMM2Hub_Parked")
    if not parked then return end
    for _, d in ipairs(parked:GetDescendants()) do
        if d:IsA("TextLabel") and d.Text == "Join Discord" then
            local parent = d.Parent
            if parent and parent:IsA("TextButton") and parent:GetAttribute("KomaruHooked") ~= true then
                local clone = parent:Clone()
                clone:SetAttribute("KomaruHooked", true)
                clone.Activated:Connect(function()
                    copy(DISCORD, "Discord")
                end)
                local label = clone:FindFirstChild("Content") and clone.Content:FindFirstChild("Label")
                if label then label.Text = "Join Discord" end
                clone.Parent = parent.Parent
                parent:Destroy()
            end
        end
    end
end

local function rebrand()
    local core = game:GetService("CoreGui"):FindFirstChild("RobloxGui")
    if not core then return false end
    local hub = core:FindFirstChild("PulseMM2Hub")
    if not hub then return false end

    local seen = getgenv().__komaruSeen
    if not seen then
        seen = setmetatable({}, { __mode = "k" })
        getgenv().__komaruSeen = seen
    end

    local function translate(text)
        if type(text) ~= "string" or #text == 0 then return text end
        local out = text
        for a, b in pairs(MAP) do
            out = string.gsub(out, a, b)
        end
        return out
    end

    local function watch(inst)
        if seen[inst] then return end
        seen[inst] = true
        inst:GetPropertyChangedSignal("Text"):Connect(function()
            local out = translate(inst.Text)
            if out ~= inst.Text then inst.Text = out end
        end)
    end

    local function patch(parent, depth)
        if depth > 14 then return end
        for _, child in ipairs(parent:GetChildren()) do
            if child.ClassName == "TextLabel" or child.ClassName == "TextButton" or child.ClassName == "TextBox" then
                local out = translate(child.Text)
                if out ~= child.Text then child.Text = out end
                watch(child)
            end
            patch(child, depth + 1)
        end
    end

    local npcHud = core:FindFirstChild("PulseNpcHud")
    if npcHud then npcHud:Destroy() end

    for _, name in ipairs({ "PulseMM2Hub", "PulseMM2Hub_Parked", "PulseMobileBtns", "PulseBBMirror", "PulsePlayerMenuUI", "PulsePlayerMenuCard" }) do
        local gui = core:FindFirstChild(name)
        if gui then patch(gui, 0) end
    end


    local window = hub:FindFirstChild("Root") and hub.Root:FindFirstChild("Window")
    local main = window and window:FindFirstChild("Main")
    local header = main and main:FindFirstChild("Header")
    if header then
        if not header:FindFirstChild("Discord") then
            makeButton(header, "Discord", -62, nil, GIRL, DISCORD)
        end
        if not header:FindFirstChild("Telegram") then
            makeButton(header, "Telegram", -100, nil, TG_ICON, TELEGRAM)
        end
    end

    patchJoinDiscord(core)
    applyLogo(hub)
    return true
end

